#include "unity.h"
#include "wav_storage.h"
#include <string.h>

void setUp(void) {}
void tearDown(void) {}

/* Parse a buffer that holds the whole file (buf_len == file_size), which is
 * what the old wav_parse_header(buf, len, out) calls meant. Tests that supply
 * only the start of a longer file call wav_parse_header() directly. */
static storage_result_t parse_file(const uint8_t *buf, size_t len, wav_header_t *out)
{
    return wav_parse_header(buf, len, (uint32_t)len, out);
}

/* ---------- wav_build_header ---------- */

void test_build_header_valid_produces_correct_bytes(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    storage_result_t result = wav_build_header(16000U, 16U, 1U, 1000U, buf, sizeof(buf));

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_MEMORY("RIFF", &buf[0], 4);
    TEST_ASSERT_EQUAL_MEMORY("WAVE", &buf[8], 4);
    TEST_ASSERT_EQUAL_MEMORY("fmt ", &buf[12], 4);
    TEST_ASSERT_EQUAL_MEMORY("data", &buf[36], 4);
}

void test_build_header_round_trips_through_parse(void)
{
    /* A real caller supplies the header AND the payload it describes -
     * build a buffer that actually contains both, matching real usage
     * (see also the "declared size" tests below). */
    const uint32_t data_size = 5000U;
    uint8_t buf[WAV_HEADER_SIZE + 5000U];

    TEST_ASSERT_EQUAL(STORAGE_OK,
        wav_build_header(44100U, 16U, 2U, data_size, buf, WAV_HEADER_SIZE));
    memset(&buf[WAV_HEADER_SIZE], 0, data_size);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, parse_file(buf, sizeof(buf), &parsed));
    TEST_ASSERT_EQUAL_UINT32(44100U, parsed.sample_rate);
    TEST_ASSERT_EQUAL_UINT16(16U, parsed.bits_per_sample);
    TEST_ASSERT_EQUAL_UINT16(2U, parsed.num_channels);
    TEST_ASSERT_EQUAL_UINT32(data_size, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(WAV_HEADER_SIZE, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(data_size, parsed.declared_data_size);
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_build_header_rejects_buffer_too_small(void)
{
    uint8_t buf[WAV_HEADER_SIZE - 1U];
    storage_result_t result = wav_build_header(16000U, 16U, 1U, 100U, buf, sizeof(buf));
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, result);
}

