void test_build_header_accepts_min_and_max_valid_sample_rates(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    /* AR1: design range is 20kHz-48kHz, but the encoder itself should
     * accept the full uint32 range above zero - range enforcement for
     * the system's supported rates is a separate policy check. */
    TEST_ASSERT_EQUAL(STORAGE_OK, wav_build_header(1U, 8U, 1U, 0U, buf, sizeof(buf)));
    TEST_ASSERT_EQUAL(STORAGE_OK, wav_build_header(192000U, 32U, 2U, 0U, buf, sizeof(buf)));
}

/* ---------- wav_parse_header ---------- */

void test_parse_header_rejects_truncated_buffer(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 100U, buf, sizeof(buf));

    wav_header_t parsed;
    /* The whole file is 20 bytes: it ends inside the fmt chunk. */
    storage_result_t result = parse_file(buf, 20U, &parsed);
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, result);
}

void test_parse_header_rejects_bad_riff_magic(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 100U, buf, sizeof(buf));
    memcpy(&buf[0], "JUNK", 4);

    wav_header_t parsed;
    storage_result_t result = parse_file(buf, sizeof(buf), &parsed);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, result);
}

void test_parse_header_rejects_non_pcm_format(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 100U, buf, sizeof(buf));
    buf[20] = 3U; /* AudioFormat = 3 (IEEE float), unsupported */
    buf[21] = 0U;

    wav_header_t parsed;
    storage_result_t result = parse_file(buf, sizeof(buf), &parsed);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, result);
}

void test_parse_header_clamps_declared_size_larger_than_supplied_data(void)
{
    uint8_t buf[WAV_HEADER_SIZE + 10U];
    wav_build_header(16000U, 16U, 1U, 100U, buf, WAV_HEADER_SIZE);
    /* Header claims 100 bytes of PCM data follow, but the file only
     * holds 10 bytes after the header (cut short). This used to be
     * rejected; the tolerant parser plays what is there and says so. */
    memset(&buf[WAV_HEADER_SIZE], 0, 10U);

    wav_header_t parsed;
    storage_result_t result = parse_file(buf, sizeof(buf), &parsed);
    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(10U, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(100U, parsed.declared_data_size);
    TEST_ASSERT_TRUE(parsed.data_size_clamped);
}

void test_parse_header_accepts_declared_size_exactly_matching_supplied_data(void)
{
    uint8_t buf[WAV_HEADER_SIZE + 10U];
    wav_build_header(16000U, 16U, 1U, 10U, buf, WAV_HEADER_SIZE);
    memset(&buf[WAV_HEADER_SIZE], 0xAB, 10U);

    wav_header_t parsed;
    storage_result_t result = parse_file(buf, sizeof(buf), &parsed);
    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(10U, parsed.data_size);
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_parse_header_rejects_null_pointers(void)
{
    wav_header_t parsed;
    uint8_t buf[WAV_HEADER_SIZE];
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        wav_parse_header(NULL, sizeof(buf), (uint32_t)sizeof(buf), &parsed));
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        wav_parse_header(buf, sizeof(buf), (uint32_t)sizeof(buf), NULL));
}


/* ---------- field-level verification ---------- */

void test_build_header_writes_correct_byte_rate_and_block_align(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 2U, 0U, buf, sizeof(buf));

    /* block_align = channels * bytes_per_sample = 2 * 2 = 4 */
    uint16_t block_align = (uint16_t)(buf[32] | ((uint16_t)buf[33] << 8));
    TEST_ASSERT_EQUAL_UINT16(4U, block_align);

    /* byte_rate = sample_rate * block_align = 16000 * 4 = 64000 */
    uint32_t byte_rate = (uint32_t)buf[28] | ((uint32_t)buf[29] << 8) |
                         ((uint32_t)buf[30] << 16) | ((uint32_t)buf[31] << 24);
    TEST_ASSERT_EQUAL_UINT32(64000U, byte_rate);
}

void test_build_header_writes_riff_chunk_size_as_36_plus_data(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 1000U, buf, sizeof(buf));

    uint32_t riff_size = (uint32_t)buf[4] | ((uint32_t)buf[5] << 8) |
                         ((uint32_t)buf[6] << 16) | ((uint32_t)buf[7] << 24);
    TEST_ASSERT_EQUAL_UINT32(1036U, riff_size);
}

void test_build_header_declares_pcm_format_and_subchunk_size(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));

    uint32_t fmt_size = (uint32_t)buf[16] | ((uint32_t)buf[17] << 8) |
                        ((uint32_t)buf[18] << 16) | ((uint32_t)buf[19] << 24);
    uint16_t audio_format = (uint16_t)(buf[20] | ((uint16_t)buf[21] << 8));

    TEST_ASSERT_EQUAL_UINT32(16U, fmt_size);
    TEST_ASSERT_EQUAL_UINT16(1U, audio_format);
}

void test_build_header_is_written_little_endian(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(0x12345678U, 16U, 1U, 0U, buf, sizeof(buf));

    /* Least significant byte must come first regardless of host endianness. */
    TEST_ASSERT_EQUAL_UINT8(0x78U, buf[24]);
    TEST_ASSERT_EQUAL_UINT8(0x56U, buf[25]);
    TEST_ASSERT_EQUAL_UINT8(0x34U, buf[26]);
    TEST_ASSERT_EQUAL_UINT8(0x12U, buf[27]);
}

