/* ---------- further parse rejection cases ---------- */

void test_parse_header_rejects_bad_wave_magic(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));
    memcpy(&buf[8], "XXXX", 4);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, parse_file(buf, sizeof(buf), &parsed));
}

void test_parse_header_rejects_bad_fmt_magic(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));
    memcpy(&buf[12], "XXXX", 4);

    /* "XXXX" is now just an unknown chunk that gets skipped, which leaves
     * the file with no fmt chunk before "data". */
    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, parse_file(buf, sizeof(buf), &parsed));
}

void test_parse_header_rejects_missing_data_chunk(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));
    memcpy(&buf[36], "LIST", 4);

    /* The chunks end exactly at the end of the file without a "data". */
    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, parse_file(buf, sizeof(buf), &parsed));
}

void test_parse_header_rejects_fmt_size_that_runs_into_the_data_chunk(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));
    buf[16] = 18U; /* fmt now claims 18 bytes, but "data" still starts at 36 */

    /* An 18-byte fmt is fine in itself (see the fixture tests below); here
     * it swallows the start of the data chunk header, so the walk lands
     * mid-chunk at byte 38 and runs off the end of the 44-byte file. */
    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, parse_file(buf, sizeof(buf), &parsed));
}

