void test_parse_header_accepts_header_only_file_with_zero_data(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, parse_file(buf, sizeof(buf), &parsed));
    TEST_ASSERT_EQUAL_UINT32(0U, parsed.data_size);
    /* 0 is a placeholder size, but nothing follows the header, so the
     * clamp changes nothing and is not reported. */
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_parse_header_round_trips_all_bit_depths(void)
{
    const uint16_t depths[] = {8U, 16U, 24U, 32U};
    for (size_t i = 0U; i < 4U; i++)
    {
        uint8_t buf[WAV_HEADER_SIZE];
        wav_build_header(44100U, depths[i], 1U, 0U, buf, sizeof(buf));

        wav_header_t parsed;
        TEST_ASSERT_EQUAL(STORAGE_OK, parse_file(buf, sizeof(buf), &parsed));
        TEST_ASSERT_EQUAL_UINT16(depths[i], parsed.bits_per_sample);
    }
}

/* ---------- RIFF fixtures: PC-style headers built chunk by chunk ---------- */

#define FX_RATE        32000U
#define FX_PCM_BYTES   100U
#define FX_READ_BYTES  512U   /* what the firmware reads before parsing */

/* Sub-format GUIDs as they are stored in a WAVE_FORMAT_EXTENSIBLE fmt chunk. */
static const uint8_t s_guid_pcm[16] =
    { 0x01U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x10U, 0x00U,
      0x80U, 0x00U, 0x00U, 0xAAU, 0x00U, 0x38U, 0x9BU, 0x71U };
static const uint8_t s_guid_ieee_float[16] =
    { 0x03U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x10U, 0x00U,
      0x80U, 0x00U, 0x00U, 0xAAU, 0x00U, 0x38U, 0x9BU, 0x71U };

typedef struct
{
    uint8_t bytes[2048];
    size_t len;
} wav_fixture_t;

static void fx_bytes(wav_fixture_t *f, const void *src, size_t n)
{
    TEST_ASSERT_TRUE_MESSAGE(f->len + n <= sizeof(f->bytes), "fixture too big");
    memcpy(&f->bytes[f->len], src, n);
    f->len += n;
}

static void fx_fill(wav_fixture_t *f, uint8_t value, size_t n)
{
    TEST_ASSERT_TRUE_MESSAGE(f->len + n <= sizeof(f->bytes), "fixture too big");
    memset(&f->bytes[f->len], value, n);
    f->len += n;
}

static void fx_u16(wav_fixture_t *f, uint16_t v)
{
    const uint8_t b[2] = { (uint8_t)(v & 0xFFU), (uint8_t)(v >> 8) };
    fx_bytes(f, b, sizeof(b));
}

static void fx_u32(wav_fixture_t *f, uint32_t v)
{
    const uint8_t b[4] = { (uint8_t)(v & 0xFFU), (uint8_t)((v >> 8) & 0xFFU),
                           (uint8_t)((v >> 16) & 0xFFU), (uint8_t)(v >> 24) };
    fx_bytes(f, b, sizeof(b));
}

/* "RIFF" <size> "WAVE"; fx_finish() fills the size in. */
static void fx_begin(wav_fixture_t *f)
{
    f->len = 0U;
    fx_bytes(f, "RIFF", 4U);
    fx_u32(f, 0U);
    fx_bytes(f, "WAVE", 4U);
}

static void fx_finish(wav_fixture_t *f)
{
    const uint32_t riff_size = (uint32_t)(f->len - 8U);
    f->bytes[4] = (uint8_t)(riff_size & 0xFFU);
    f->bytes[5] = (uint8_t)((riff_size >> 8) & 0xFFU);
    f->bytes[6] = (uint8_t)((riff_size >> 16) & 0xFFU);
    f->bytes[7] = (uint8_t)(riff_size >> 24);
}

/* A chunk the parser has to skip: its header, size bytes of filler (not
 * zero, so a misread offset shows up) and the pad byte RIFF puts after an
 * odd-sized chunk. */
static void fx_chunk(wav_fixture_t *f, const char *id, uint32_t size)
{
    fx_bytes(f, id, 4U);
    fx_u32(f, size);
    fx_fill(f, 0xA5U, size);
    if ((size & 1U) != 0U)
    {
        fx_fill(f, 0x00U, 1U);
    }
}

/* Plain "fmt ": the 16 PCM fields, then zeros up to chunk_size (an 18-byte
 * chunk is WAVEFORMATEX with cbSize = 0, as Windows and ffmpeg write it). */
static void fx_fmt(wav_fixture_t *f, uint32_t chunk_size, uint16_t format,
                   uint16_t channels, uint16_t bits)
{
    const uint16_t block_align = (uint16_t)(channels * (bits / 8U));
    fx_bytes(f, "fmt ", 4U);
    fx_u32(f, chunk_size);
    fx_u16(f, format);
    fx_u16(f, channels);
    fx_u32(f, FX_RATE);
    fx_u32(f, FX_RATE * block_align);
    fx_u16(f, block_align);
    fx_u16(f, bits);
    fx_fill(f, 0x00U, chunk_size - 16U);
}

/* WAVE_FORMAT_EXTENSIBLE "fmt " (40 bytes) with the given sub-format. */
static void fx_fmt_extensible(wav_fixture_t *f, uint16_t channels, uint32_t rate,
                              uint16_t bits, const uint8_t guid[16])
{
    const uint16_t block_align = (uint16_t)(channels * (bits / 8U));
    fx_bytes(f, "fmt ", 4U);
    fx_u32(f, 40U);
    fx_u16(f, 0xFFFEU);
    fx_u16(f, channels);
    fx_u32(f, rate);
    fx_u32(f, rate * block_align);
    fx_u16(f, block_align);
    fx_u16(f, bits);
    fx_u16(f, 22U);                  /* cbSize */
    fx_u16(f, bits);                 /* valid bits per sample */
    fx_u32(f, (channels == 1U) ? 0x4U : 0x3U);   /* channel mask */
    fx_bytes(f, guid, 16U);
}

/* "data" <declared size> + pcm_bytes of samples. Returns the offset of the
 * first sample. */
static size_t fx_data(wav_fixture_t *f, uint32_t declared, size_t pcm_bytes)
{
    fx_bytes(f, "data", 4U);
    fx_u32(f, declared);
    const size_t offset = f->len;
    fx_fill(f, 0x11U, pcm_bytes);
    return offset;
}

/* What the firmware does: hand over at most the first 512 bytes, plus the
 * size of the whole file. */
static storage_result_t fx_parse(const wav_fixture_t *f, wav_header_t *out)
{
    const size_t buf_len = (f->len < FX_READ_BYTES) ? f->len : FX_READ_BYTES;
    return wav_parse_header(f->bytes, buf_len, (uint32_t)f->len, out);
}

void test_fixture_builds_the_same_canonical_header_as_wav_build_header(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    uint8_t expected[WAV_HEADER_SIZE];
    TEST_ASSERT_EQUAL(STORAGE_OK,
        wav_build_header(FX_RATE, 16U, 1U, FX_PCM_BYTES, expected, sizeof(expected)));
    TEST_ASSERT_EQUAL_MEMORY(expected, fx.bytes, WAV_HEADER_SIZE);
}

void test_parse_canonical_header_reports_data_at_byte_44(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    const size_t offset = fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_size_t(WAV_HEADER_SIZE, offset);
    TEST_ASSERT_EQUAL_UINT32(WAV_HEADER_SIZE, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(FX_RATE, parsed.sample_rate);
    TEST_ASSERT_EQUAL_UINT16(16U, parsed.bits_per_sample);
    TEST_ASSERT_EQUAL_UINT16(1U, parsed.num_channels);
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_parse_accepts_only_the_first_44_bytes_of_a_long_recording(void)
{
    /* A 10 s recording: the caller has just the header in its buffer. */
    uint8_t buf[WAV_HEADER_SIZE];
    TEST_ASSERT_EQUAL(STORAGE_OK, wav_build_header(32000U, 16U, 1U, 640000U, buf, sizeof(buf)));

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK,
        wav_parse_header(buf, sizeof(buf), WAV_HEADER_SIZE + 640000U, &parsed));
    TEST_ASSERT_EQUAL_UINT32(WAV_HEADER_SIZE, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(640000U, parsed.data_size);
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_parse_skips_a_list_chunk_before_data(void)
{
    /* ffmpeg's default output: an INFO list (encoder name) before "data". */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "LIST", 26U);
    const size_t offset = fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_size_t(78U, offset);
    TEST_ASSERT_EQUAL_UINT32(78U, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT16(1U, parsed.num_channels);
    TEST_ASSERT_EQUAL_UINT16(16U, parsed.bits_per_sample);
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_parse_accepts_an_18_byte_fmt_chunk(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 18U, 1U, 1U, 16U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(46U, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(FX_RATE, parsed.sample_rate);
}

void test_parse_accepts_extensible_fmt_with_the_pcm_subformat(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt_extensible(&fx, 2U, 48000U, 24U, s_guid_pcm);
    (void)fx_data(&fx, 96U, 96U);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(68U, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(96U, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(48000U, parsed.sample_rate);
    TEST_ASSERT_EQUAL_UINT16(2U, parsed.num_channels);
    TEST_ASSERT_EQUAL_UINT16(24U, parsed.bits_per_sample);
}

void test_parse_rejects_extensible_fmt_with_a_float_subformat(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt_extensible(&fx, 1U, FX_RATE, 32U, s_guid_ieee_float);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, fx_parse(&fx, &parsed));
}

void test_parse_rejects_extensible_fmt_too_short_for_its_subformat(void)
{
    /* Format tag 0xFFFE in an 18-byte chunk: no room for the GUID. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 18U, 0xFFFEU, 1U, 16U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, fx_parse(&fx, &parsed));
}

void test_parse_rejects_fmt_chunk_shorter_than_16_bytes(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_bytes(&fx, "fmt ", 4U);
    fx_u32(&fx, 14U);                  /* WAVEFORMAT without wBitsPerSample */
    fx_u16(&fx, 1U);
    fx_u16(&fx, 1U);
    fx_u32(&fx, FX_RATE);
    fx_u32(&fx, FX_RATE * 2U);
    fx_u16(&fx, 2U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, fx_parse(&fx, &parsed));
}

void test_parse_finds_fmt_after_other_chunks(void)
{
    /* Broadcast-WAV style: JUNK and bext first, fmt and fact later. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_chunk(&fx, "JUNK", 28U);
    fx_chunk(&fx, "bext", 10U);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "fact", 4U);
    const size_t offset = fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_size_t(110U, offset);
    TEST_ASSERT_EQUAL_UINT32(110U, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(FX_RATE, parsed.sample_rate);
    TEST_ASSERT_EQUAL_UINT16(16U, parsed.bits_per_sample);
}

void test_parse_rejects_data_before_any_fmt_chunk(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    (void)fx_data(&fx, 4U, 4U);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, fx_parse(&fx, &parsed));
}

void test_parse_honours_the_pad_byte_after_an_odd_sized_chunk(void)
{
    /* 7-byte unknown chunk + 1 pad byte: "data" starts at 36 + 8 + 8 = 52.
     * Ignoring the pad would read the chunk id one byte early. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "abcd", 7U);
    const size_t offset = fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_size_t(60U, offset);
    TEST_ASSERT_EQUAL_UINT32(60U, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
}

void test_parse_rejects_a_file_that_ends_inside_a_chunk(void)
{
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "LIST", 26U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    /* The whole (short) file: cut inside the LIST chunk, then inside the
     * data chunk header. Nothing follows, so both are truncated headers. */
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, parse_file(fx.bytes, 60U, &parsed));
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, parse_file(fx.bytes, 74U, &parsed));
}

void test_parse_rejects_a_buffer_longer_than_the_file(void)
{
    uint8_t buf[WAV_HEADER_SIZE];
    wav_build_header(16000U, 16U, 1U, 0U, buf, sizeof(buf));

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        wav_parse_header(buf, sizeof(buf), WAV_HEADER_SIZE - 4U, &parsed));
}

void test_parse_with_fewer_than_44_bytes_of_a_longer_file(void)
{
    uint8_t buf[WAV_HEADER_SIZE + 100U];
    wav_build_header(16000U, 16U, 1U, 100U, buf, WAV_HEADER_SIZE);
    memset(&buf[WAV_HEADER_SIZE], 0, 100U);

    wav_header_t parsed;
    /* "data" is not inside the first 30 bytes; the file goes on. */
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND,
        wav_parse_header(buf, 30U, (uint32_t)sizeof(buf), &parsed));
    /* Not even "RIFF" <size> "WAVE" fits in 11 bytes. */
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        wav_parse_header(buf, 11U, (uint32_t)sizeof(buf), &parsed));
}

void test_parse_clamps_a_data_size_of_zero(void)
{
    /* A streaming writer that never came back to fill the size in. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    (void)fx_data(&fx, 0U, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(0U, parsed.declared_data_size);
    TEST_ASSERT_TRUE(parsed.data_size_clamped);
}

void test_parse_clamps_an_unknown_data_size_0xFFFFFFFF(void)
{
    /* ffmpeg writing to a pipe: RIFF and data sizes both 0xFFFFFFFF. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    (void)fx_data(&fx, 0xFFFFFFFFU, FX_PCM_BYTES);
    memset(&fx.bytes[4], 0xFF, 4U);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(0xFFFFFFFFU, parsed.declared_data_size);
    TEST_ASSERT_TRUE(parsed.data_size_clamped);
}

void test_parse_clamps_a_data_size_larger_than_the_file(void)
{
    /* A long file cut short: only the first 512 bytes are supplied, the
     * clamp works from the file size. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    (void)fx_data(&fx, 100000U, 1000U);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(WAV_HEADER_SIZE, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(1000U, parsed.data_size);
    TEST_ASSERT_EQUAL_UINT32(100000U, parsed.declared_data_size);
    TEST_ASSERT_TRUE(parsed.data_size_clamped);
}

void test_parse_keeps_a_data_size_followed_by_trailing_chunks(void)
{
    /* Audacity puts tags after the samples: the data size is smaller than
     * the rest of the file, which is fine and is not clamped. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_chunk(&fx, "id3 ", 40U);
    fx_finish(&fx);

    wav_header_t parsed;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);
    TEST_ASSERT_FALSE(parsed.data_size_clamped);
}

void test_parse_reports_a_data_chunk_beyond_the_first_512_bytes(void)
{
    /* A 600-byte JUNK chunk pushes "data" to byte 644. */
    wav_fixture_t fx;
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "JUNK", 600U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);

    wav_header_t parsed;
    memset(&parsed, 0x5A, sizeof(parsed));
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(0x5A5A5A5AU, parsed.sample_rate);   /* untouched on rejection */

    /* The limit is the caller's buffer, not the parser: given the whole
     * file it finds the chunk. */
    TEST_ASSERT_EQUAL(STORAGE_OK, parse_file(fx.bytes, fx.len, &parsed));
    TEST_ASSERT_EQUAL_UINT32(652U, parsed.data_offset);
}

void test_parse_needs_the_whole_data_chunk_header_inside_the_buffer(void)
{
    wav_header_t parsed;
    wav_fixture_t fx;

    /* JUNK of 460 bytes: the data chunk header is bytes 504..511, the last
     * eight of the 512 read - just fits. */
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "JUNK", 460U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse(&fx, &parsed));
    TEST_ASSERT_EQUAL_UINT32(512U, parsed.data_offset);
    TEST_ASSERT_EQUAL_UINT32(FX_PCM_BYTES, parsed.data_size);

    /* JUNK of 464 bytes: the header starts at 508 and straddles the end. */
    fx_begin(&fx);
    fx_fmt(&fx, 16U, 1U, 1U, 16U);
    fx_chunk(&fx, "JUNK", 464U);
    (void)fx_data(&fx, FX_PCM_BYTES, FX_PCM_BYTES);
    fx_finish(&fx);
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, fx_parse(&fx, &parsed));
}

void test_parse_does_not_wrap_on_chunk_sizes_near_4_gb(void)
{
    /* Sizes that would wrap a 32-bit offset if added up blindly (with an
     * odd size the pad byte makes 0xFFFFFFFF + 1 = 0). The walk must stop,
     * not jump back or loop. */
    const uint32_t sizes[] = { 0xFFFFFFFFU, 0xFFFFFFF8U, 0x80000000U };
    for (size_t i = 0U; i < 3U; i++)
    {
        wav_fixture_t fx;
        fx_begin(&fx);
        fx_fmt(&fx, 16U, 1U, 1U, 16U);
        fx_bytes(&fx, "LIST", 4U);
        fx_u32(&fx, sizes[i]);
        fx_fill(&fx, 0xA5U, 600U);       /* the file really goes on past 512 */
        fx_finish(&fx);

        wav_header_t parsed;
        TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, fx_parse(&fx, &parsed));
        /* Whole file in the buffer: the chunk runs past the end of it. */
        TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, parse_file(fx.bytes, fx.len, &parsed));
    }
}

/* ---------- wav_duration_ms (drives the UI file list) ---------- */

void test_duration_typical_one_second_recording(void)
{
    /* 16 kHz, 16-bit mono = 32000 bytes per second. */
    wav_header_t h = { .sample_rate = 16000U, .bits_per_sample = 16U,
                       .num_channels = 1U, .data_size = 32000U };
    TEST_ASSERT_EQUAL_UINT32(1000U, wav_duration_ms(&h));
}

void test_duration_stereo_is_half_of_mono_for_same_byte_count(void)
{
    wav_header_t mono   = { .sample_rate = 16000U, .bits_per_sample = 16U,
                            .num_channels = 1U, .data_size = 32000U };
    wav_header_t stereo = { .sample_rate = 16000U, .bits_per_sample = 16U,
                            .num_channels = 2U, .data_size = 32000U };
    TEST_ASSERT_EQUAL_UINT32(1000U, wav_duration_ms(&mono));
    TEST_ASSERT_EQUAL_UINT32(500U,  wav_duration_ms(&stereo));
}

void test_duration_of_empty_recording_is_zero(void)
{
    wav_header_t h = { .sample_rate = 16000U, .bits_per_sample = 16U,
                       .num_channels = 1U, .data_size = 0U };
    TEST_ASSERT_EQUAL_UINT32(0U, wav_duration_ms(&h));
}

void test_duration_rejects_null_header(void)
{
    TEST_ASSERT_EQUAL_UINT32(0U, wav_duration_ms(NULL));
}

void test_duration_rejects_invalid_format_fields(void)
{
    wav_header_t zero_rate     = { .sample_rate = 0U,     .bits_per_sample = 16U,
                                   .num_channels = 1U, .data_size = 32000U };
    wav_header_t zero_channels = { .sample_rate = 16000U, .bits_per_sample = 16U,
                                   .num_channels = 0U, .data_size = 32000U };
    wav_header_t zero_bits     = { .sample_rate = 16000U, .bits_per_sample = 0U,
                                   .num_channels = 1U, .data_size = 32000U };
    wav_header_t odd_bits      = { .sample_rate = 16000U, .bits_per_sample = 12U,
                                   .num_channels = 1U, .data_size = 32000U };

    TEST_ASSERT_EQUAL_UINT32(0U, wav_duration_ms(&zero_rate));
    TEST_ASSERT_EQUAL_UINT32(0U, wav_duration_ms(&zero_channels));
    TEST_ASSERT_EQUAL_UINT32(0U, wav_duration_ms(&zero_bits));
    TEST_ASSERT_EQUAL_UINT32(0U, wav_duration_ms(&odd_bits));
}

void test_duration_does_not_overflow_on_long_recording(void)
{
    /* ~100 MB of 48 kHz 16-bit mono audio - data_size * 1000 exceeds 32 bits. */
    wav_header_t h = { .sample_rate = 48000U, .bits_per_sample = 16U,
                       .num_channels = 1U, .data_size = 96000000U };
    TEST_ASSERT_EQUAL_UINT32(1000000U, wav_duration_ms(&h));
}

